import type { ReactNode } from 'react';

/* Section headings carry their own weight, no kicker labels above them. */
export function SectionHead({
  title, lead, id,
}: { title: ReactNode; lead?: string; id?: string }) {
  return (
    <div id={id} className="mb-14 max-w-3xl">
      <h2 className="text-[clamp(1.7rem,3.4vw,2.6rem)] font-normal leading-[1.1] tracking-[-0.04em] text-ink-50">
        {title}
      </h2>
      {lead && <p className="mt-4 max-w-[62ch] text-[0.95rem] leading-relaxed text-ink-400">{lead}</p>}
    </div>
  );
}

export function Shell({ children, className = '' }: { children: ReactNode; className?: string }) {
  return <div className={`mx-auto w-full max-w-7xl px-6 lg:px-10 ${className}`}>{children}</div>;
}
