import landing from './landing.json';
import cases from './cases.json';

export type Work = {
  href: string; img: string; idx: string; h3: string; p: string;
  northStar: string; tags: string[]; meta: string;
};
export type Build = {
  img: string; h3: string; tag: string; p: string; stack: string[];
  live: string | null; github: string; note: string;
};
export type Cap = { h3: string; p: string };
export type Xp = {
  when: string; where: string; role: string; co: string;
  bullets: string[]; chips: string[];
};
export type CaseStudy = {
  slug: string; title: string; description: string;
  ogTitle: string; ogDesc: string; ogImage: string;
  kicker: string; h1: string; sub: string;
  tags: string[]; meta: [string, string][]; toc: [string, string][];
  prose: string; next: [string, string, string][];
};

const strip = (s: string) => s.replace(/<[^>]+>/g, '').replace(/&amp;/g, '&').trim();

export const works = landing.works as unknown as Work[];
export const builds = landing.builds as unknown as Build[];
export const caps = landing.caps as unknown as Cap[];
export const xp = landing.xp as unknown as Xp[];
export const stats = landing.stats as unknown as [string, string][];
export const ticker = landing.ticker as string[];
export const contact = landing.contact as unknown as [string, string, string][];
export const aboutParas = (landing.aboutParas as string[]).map((p) => p);
export const caseStudies = cases as unknown as CaseStudy[];

export const bySlug = (slug: string) => caseStudies.find((c) => c.slug === slug);
export const plain = strip;
